// 🔴 真實踩過的坑（本機用 matrix/arcrun 的 GraphExecutor 真跑過才發現，不是猜的）：
// {{input.xxx}} 在 xxx 這個 key 真的不存在時，GraphExecutor 的 interpolateString
// 會回「原樣保留這個 {{...}} 字面字串」，不是 undefined、也不是空字串
// （matrix/arcrun/cypher-executor/src/graph-executor.ts interpolateString 的既有設計：
//  「找不到就保留字面字串」，是引擎故意的行為，不是 bug）。
// ⇒ 呼叫端漏帶 date 時，這裡收到的 input.date 不是 undefined，是字串 "{{input.date}}"
//   ——若只判斷 == null || === ''，這個字面字串會被誤判成「有給值」，
//   然後在 YYYY-MM-DD 格式檢查那關失敗，讓「不帶 date 就用今天」整個失效。
// 修法：多判一種「看起來像沒解開的模板」的形狀，視同沒給。
function provided(v) {
  if (typeof v !== 'string') return false;
  var t = v.trim();
  return t !== '' && !/^\{\{[\s\S]*\}\}$/.test(t);
}
const content = provided(input.content) ? String(input.content).trim() : '';
if (!content) return { success: false, error: 'content 不可為空（筆記至少要有內容）' };
const now = new Date();
const rawDate = provided(input.date) ? String(input.date).trim() : now.toISOString().slice(0, 10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(rawDate)) {
  return { success: false, error: 'date 必須是 YYYY-MM-DD 格式（收到：' + rawDate + '）' };
}
// parent_id：省略／空字串＝一則獨立筆記；非空＝這是某則筆記的回覆（值＝那則的 record_id）。
// 沒有格式限制（record_id 的形狀由 KBDB 決定，這裡不重複驗證它的長相）——
// 這樣前端不用先知道 record_id 的格式規則，只要「原樣把上一步拿到的 id 傳回來」就對。
const parentId = provided(input.parent_id) ? String(input.parent_id).trim() : '';
// quote／quote_pos（arcrun-app-note#2）：這則回覆引用了原文哪一段、那段在原文第幾個字。
// 只有回覆會帶；獨立筆記一律存空字串（不信任呼叫端對獨立筆記帶的 quote）。
const quote = parentId && provided(input.quote) ? String(input.quote).trim().slice(0, 300) : '';
// 畫面送來的是數字；經 HTTP／模板也可能變字串——兩種都收，沒給就是空（不是 0）。
const qp = typeof input.quote_pos === 'number' ? input.quote_pos : (provided(input.quote_pos) ? Number(input.quote_pos) : NaN);
const quotePos = quote && isFinite(qp) && qp >= 0 ? String(Math.floor(qp)) : '';
// author（arcrun-app-note#2）：只認引擎簽的 Portal 斷言（_portal_actor）裡的登入名——
// 呼叫端自帶的同名欄位在 /portal/data/apps/:id/action 那一關就被丟掉了。沒有斷言＝作者留空
// （空作者＝舊資料／沒簽章金鑰的實例，編輯刪除的判斷把它當「任何登入者都能動」，見 update_note）。
function loginOf(a) {
  if (typeof a === 'string') { a = provided(a) ? a : ''; if (a) { try { a = JSON.parse(a); } catch (e) { a = null; } } else { a = null; } }
  return a && typeof a === 'object' && typeof a.login === 'string' ? a.login.trim().slice(0, 128) : '';
}
return { success: true, content: content, date: rawDate, created_at: now.toISOString(), parent_id: parentId,
         author: loginOf(input.actor), quote: quote, quote_pos: quotePos };

function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
const body = parse(input.body);
return { success: true, record_id: body && body.record && body.record.record_id ? String(body.record.record_id) : '' };

function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
const body = parse(input.body);
if (!body || body.success !== true || !body.record) {
  return { success: false, error: (body && body.error) || 'KBDB 寫入沒有回可用的 record' };
}
const v = body.record.values || {};
return {
  success: true,
  record_id: body.record.record_id,
  date: v.date || '',
  content: v.content || '',
  created_at: v.created_at || '',
  parent_id: v.parent_id || '',
  author: v.author || '',
  quote: v.quote || '',
  quote_pos: v.quote_pos || '',
};

// 🔴 真實踩過的坑（本機用 matrix/arcrun 的 GraphExecutor 真跑過才發現——
// 不加這段防護時，「不帶 date＝查全部」這個最常用的預設路徑會靜默回傳 0 筆，
// 詳細成因見 notes-create.yaml 的 prep 節點同款註解，這裡不重複貼一次）。
function provided(v) {
