}
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
function loginOf(a) {
  if (typeof a === 'string') { a = provided(a) ? a : ''; if (a) { try { a = JSON.parse(a); } catch (e) { a = null; } } else { a = null; } }
  return a && typeof a === 'object' && typeof a.login === 'string' ? a.login.trim().slice(0, 128) : '';
}
const body = parse(input.body) || {};
const records = Array.isArray(body.records) ? body.records : [];
const wantDate = provided(input.date) ? String(input.date).trim() : '';
const all = records.map(function (r) {
  const v = r.values || {};
  return {
    record_id: r.record_id,
    date: v.date || '',
    content: v.content || '',
    created_at: v.created_at || '',
    edited_at: v.edited_at || '',
    parent_id: v.parent_id || '',
    author: v.author || '',
    quote: v.quote || '',
    quote_pos: v.quote_pos || '',
    deleted: v.deleted === '1'
  };
});
// 已刪除（arcrun-app-note#2，標記刪除、不物理刪除）：
//   · 已刪除的獨立筆記整則不出現，它底下的回覆跟著不出現；
//   · 已刪除的回覆：它「之後」還有別人的回覆時留一個占位（deleted:true，內文清空——刪掉的字不送到畫面），
//     之後沒有任何回覆了就不出現。畫面把占位顯示成「這則回覆已刪除」。
const deletedTop = {};
all.forEach(function (n) { if (n.deleted && !n.parent_id) deletedTop[n.record_id] = true; });
const repliesByParent = {};
all.forEach(function (n) {
  if (!n.parent_id || deletedTop[n.parent_id]) return;
  (repliesByParent[n.parent_id] = repliesByParent[n.parent_id] || []).push(n);
});
Object.keys(repliesByParent).forEach(function (pid) {
  const list = repliesByParent[pid];
  list.sort(function (a, b) { return (a.created_at || '').localeCompare(b.created_at || ''); });
  let lastLive = -1;
  list.forEach(function (r, i) { if (!r.deleted) lastLive = i; });
  repliesByParent[pid] = list.filter(function (r, i) { return !r.deleted || i < lastLive; }).map(function (r) {
    return r.deleted ? { record_id: r.record_id, parent_id: r.parent_id, created_at: r.created_at, deleted: true, content: '', author: '', quote: '', quote_pos: '' } : r;
  });
});
let notes = all.filter(function (n) { return !n.parent_id && !n.deleted; });
if (wantDate) notes = notes.filter(function (n) { return n.date === wantDate; });
notes.sort(function (a, b) { return (b.created_at || '').localeCompare(a.created_at || ''); });
notes = notes.map(function (n) {
  return Object.assign({}, n, { replies: repliesByParent[n.record_id] || [] });
});
return { success: true, notes: notes, count: notes.length, date: wantDate || null, me: loginOf(input.actor) };

