function provided(v) {
  if (typeof v !== 'string') return false;
  var t = v.trim();
  return t !== '' && !/^\{\{[\s\S]*\}\}$/.test(t);
}
const recordId = provided(input.record_id) ? String(input.record_id).trim() : '';
if (!/^[A-Za-z0-9_.:-]{1,200}$/.test(recordId)) return { success: false, error: 'record_id 必填（要整理哪一則）' };
return { success: true, record_id: recordId };

function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
const body = parse(input.body) || {};
const v = body.record && body.record.values;
if (!body.success || !v || typeof v.content !== 'string' || typeof v.date !== 'string') {
  return { success: false, error: '找不到這則筆記（可能已被刪除）' };
}
if (v.deleted === '1') return { success: false, error: '這則已經刪除，不整理' };
if (v.parent_id) return { success: false, error: '回覆不整理成卡（只整理獨立筆記）' };
const text = String(v.content).trim();
if (text.length < 10) return { success: false, error: '筆記太短（不到 10 個字），不整理成卡' };
// 上限：一則筆記再長也只送前 6000 字給模型（免得一則貼了整本書的筆記把整理拖垮）。
return { success: true, record_id: input.record_id, date: v.date, page_name: '筆記 ' + v.date, text: text.slice(0, 6000) };

function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
const body = parse(input.body);
if (!body || body.success !== true) {
  return { success: false, error: '整理失敗：' + ((body && body.error) || 'AI 沒有回應') };
}
const raw = String(body.output || '');
const i = raw.indexOf('{'), j = raw.lastIndexOf('}');
let obj = null;
if (i >= 0 && j > i) { try { obj = JSON.parse(raw.slice(i, j + 1)); } catch (e) { obj = null; } }
if (!obj || !Array.isArray(obj.cards)) return { success: false, error: '整理失敗：AI 回的不是約定的 JSON（沒有 cards 清單）' };
function str(x, n) { return typeof x === 'string' ? x.replace(/\s+/g, ' ').trim().slice(0, n) : ''; }
const source = 'note://' + input.record_id;
const cards = [];
const seen = {};
for (const c of obj.cards.slice(0, 4)) {
  if (!c || typeof c !== 'object') continue;
  const title = str(c.title, 40).replace(/[#\n]/g, '');
  const summary = str(c.summary, 300);
  const points = (Array.isArray(c.points) ? c.points : []).map(function (p) { return str(p, 300); }).filter(Boolean).slice(0, 6);
  if (!title || (!summary && points.length === 0)) continue;
  const pageName = title + '（筆記 ' + input.date + '）';
  if (seen[pageName]) continue;
  seen[pageName] = true;
  let md = '# ' + title + '\n';
  if (summary) md += '## 一句話定義\n' + summary + '\n';
  if (points.length) md += '## 要點\n' + points.map(function (p) { return '- ' + p; }).join('\n') + '\n';
  cards.push({
    page_name: pageName,
    content: md,
    // 整串 metadata 在這裡組好再傳：欄位值裡有引號時，不會把 JSON 字串弄壞。
    metadata_json: JSON.stringify({ source: source, source_path: '筆記 ' + input.date, library: 'notes', machine_label: '筆記 App', note_id: input.record_id, embed: true }),
  });
}
if (cards.length === 0) return { success: false, error: '整理失敗：AI 沒有整理出可用的卡' };
return { success: true, cards: cards, card_count: cards.length, page_names: cards.map(function (c) { return c.page_name; }) };
